1	import { createHash, randomBytes } from "node:crypto";
2	import { db } from "./db";
3	
4	// Credits already cap spend per build, but nothing stops a broken or
5	// malicious client from firing many rapid requests before a human notices —
6	// and a free, unmetered *.kodely.site subdomain is a spam/phishing vector
7	// independent of credit spend. These are coarse, cheap safety nets, not a
8	// content-moderation system (there is no classifier here — a page can still
9	// be abusive content and pass both checks; that's a separate, harder problem
10	// left for a dedicated moderation pass, not faked here with a weak heuristic).
11	
12	const GENERATE_LIMIT = 20; // per user, per rolling hour
13	const PUBLISH_LIMIT = 15; // new (first-time) publishes per user, per rolling day
14	const ENHANCE_LIMIT = 40; // per user, per rolling hour
15	
16	export async function checkGenerateRateLimit(
17	  userId: string,
18	): Promise<{ allowed: boolean; retryAfterSeconds?: number }> {
19	  const since = new Date(Date.now() - 60 * 60_000);
20	  const count = await db.build.count({
21	    where: { project: { userId }, createdAt: { gte: since } },
22	  });
23	  if (count < GENERATE_LIMIT) return { allowed: true };
24	  return { allowed: false, retryAfterSeconds: 3600 };
25	}
26	
27	export async function checkPublishRateLimit(
28	  userId: string,
29	): Promise<{ allowed: boolean; retryAfterSeconds?: number }> {
30	  const since = new Date(Date.now() - 24 * 60 * 60_000);
31	  // Counts DISTINCT projects touched by a publish in the window, not publish
32	  // events — republishing the same project repeatedly still counts once.
33	  // That's the right shape: the abuse case is many distinct spam subdomains,
34	  // not heavy iteration on one real site (which credits already gate).
35	  const count = await db.project.count({
36	    where: { userId, publishedAt: { gte: since } },
37	  });
38	  if (count < PUBLISH_LIMIT) return { allowed: true };
39	  return { allowed: false, retryAfterSeconds: 86_400 };
40	}
41	
42	// In memory, and synchronous, unlike the two checks above — an enhance leaves
43	// nothing in the database to count. It writes no files, creates no build row
44	// and charges no credits by design (see lib/enhance.ts), and a throwaway
45	// suggestion does not justify its own table. So this is per-process and resets
46	// on every deploy: a speed bump, exactly like the contact form's throttle, and
47	// the right weight for a call that costs a fraction of a cent. The real
48	// spending gate is still checkGenerateRateLimit plus the credit meter — those
49	// sit in front of the only thing here that costs real money.
50	//
51	// The ceiling is deliberately well above checkGenerateRateLimit's 20 builds an
52	// hour: enhancing several drafts before committing to one build is the whole
53	// point of the feature, and a limit that punished that would fight it.
54	const enhanceHits = new Map<string, number[]>();
55	
56	export function checkEnhanceRateLimit(userId: string): {
57	  allowed: boolean;
58	  retryAfterSeconds?: number;
59	} {
60	  const now = Date.now();
61	  const cutoff = now - 60 * 60_000;
62	  const recent = (enhanceHits.get(userId) ?? []).filter((t) => t > cutoff);
63	
64	  // Bound the map so a long-lived process can't accumulate one entry per user
65	  // forever. Clearing wholesale (rather than evicting) briefly resets everyone
66	  // — acceptable for a speed bump, and it never denies a legitimate request.
67	  if (enhanceHits.size > 5000) enhanceHits.clear();
68	
69	  if (recent.length >= ENHANCE_LIMIT) {
70	    enhanceHits.set(userId, recent);
71	    // Wait until the oldest hit in the window ages out, not a flat hour.
72	    return {
73	      allowed: false,
74	      retryAfterSeconds: Math.max(1, Math.ceil((recent[0] - cutoff) / 1000)),
75	    };
76	  }
77	
78	  recent.push(now);
79	  enhanceHits.set(userId, recent);
80	  return { allowed: true };
81	}
82	
83	// ===========================================================================
84	// PRE-AUTH limiting (login / signup)
85	// ===========================================================================
86	//
87	// Everything above keys on `userId`, so none of it can run before a session
88	// exists. Login and signup are the two routes that are reachable by anyone and
89	// that are worth attacking: unlimited password guessing on one side, and on the
90	// other a free account that is immediately granted SIGNUP_GRANT credits — real
91	// model spend, minted by a POST.
92	//
93	// STORAGE: in-memory, per-process, like the enhance limiter above and the
94	// contact form's. That is a deliberate choice under a real constraint, not an
95	// oversight — the two durable limiters above count rows that the feature
96	// already writes (Build, Project). A failed login writes nothing, so a durable
97	// counter needs somewhere to live, and there is no table for it. The honest
98	// options were (a) a new Prisma model, which is a schema change, or (b)
99	// borrowing the analytics `Event` table — rejected, because that table's
100	// contract is an explicit closed vocabulary of non-PII product events whose
101	// list the privacy policy is written from, and IP-keyed security counters are
102	// neither. So this is per-process and resets on every deploy or restart.
103	//
104	// What that costs, stated plainly:
105	//   * On restart/deploy the counters are lost — the limiter FAILS OPEN across
106	//     that boundary. An attacker cannot trigger a deploy, so this buys them one
107	//     reset at unpredictable times; it does not give them a bypass on demand.
108	//   * If the app is ever run as more than one process (it is one systemd unit
109	//     per environment today — `kodely` and `kodely-staging`), each process would
110	//     keep its own counters and the effective limit multiplies by the process
111	//     count. Anyone adding a cluster/replica MUST move this to a shared store.
112	// Promoting this to a `LoginAttempt` table is a one-model migration and is the
113	// right next step; the shape below (check → record → forget) is deliberately
114	// the shape a DB-backed implementation would have.
115	//
116	// FAIL DIRECTION: closed. A request whose client IP cannot be established (see
117	// clientIp) is not waved through — it lands in one shared, strict bucket. And
118	// the DB-backed successor should fail closed too: both auth routes read the
119	// same Postgres the limiter would live in, so a database outage already breaks
120	// login and signup. Failing closed there costs nothing that is not already lost,
121	// while failing open would turn any DB blip into an unlimited-guessing window.
122	
123	/**
124	 * The client's IP, as the key for a pre-auth bucket.
125	 *
126	 * WHICH HEADER, AND WHY IT MATTERS: this app sits behind Cloudflare → host
127	 * nginx → VM nginx, so the socket peer is always a proxy and the address has to
128	 * come from a header. Only ONE header here is trustworthy:
129	 *
130	 *  * `cf-connecting-ip` — SET by Cloudflare on every request, overwriting
131	 *    whatever the client sent. A client cannot forge it through the edge. This
132	 *    is the one we use.
133	 *  * `x-forwarded-for` FIRST entry — ATTACKER-CONTROLLED. Cloudflare *appends*
134	 *    to any XFF the client supplied rather than replacing it, so entry 0 is
135	 *    simply a string the caller chose. Keying on it means an attacker gets a
136	 *    fresh bucket per request and the limiter does nothing. (That is exactly
137	 *    finding M3 against app/api/contact/route.ts, which is why this file does
138	 *    not repeat it.)
139	 *  * `x-forwarded-for` LAST entry — useless here, though not spoofable. Each
140	 *    nginx hop appends the address of the hop *before* it, so the last entry on
141	 *    arrival is our own front nginx, a constant. Keying on it would put every
142	 *    visitor on the planet in one bucket.
143	 *
144	 * NO `cf-connecting-ip` ⇒ the request did not come through the edge (local dev,
145	 * a health check, or someone hitting the origin IP directly). Next gives a route
146	 * handler no socket address to fall back on, so all such traffic shares one
147	 * bucket named below. That is deliberate and fails closed: direct-to-origin
148	 * traffic is throttled as a single collective client rather than being exempt.
149	 *
150	 * RESIDUAL, for the record: an attacker who can reach the origin IP directly,
151	 * bypassing Cloudflare, CAN forge `cf-connecting-ip` — no application code can
152	 * detect that. The fix is at the edge, not here: restrict the origin's firewall
153	 * to Cloudflare's published ranges (or use an authenticated origin pull). That
154	 * is infrastructure work outside this repo and it is not done as far as this
155	 * checkout can tell.
156	 *
157	 * IP is also imperfect in the other direction, and knowingly so: a NAT'd office
158	 * or a carrier-grade NAT presents hundreds of real people as one key. The limits
159	 * below are sized with that in mind, and login refunds successful attempts
160	 * (see noteLoginSuccess) precisely so a busy shared address is not spent by
161	 * people who typed their password correctly.
162	 */
163	function clientIp(req: Request): string {
164	  const cf = req.headers.get("cf-connecting-ip")?.trim();
165	  if (cf) return cf.toLowerCase();
166	  return "no-edge";
167	}
168	
169	// Emails are hashed before they are used as a map key, with a salt that lives
170	// only in this process. The map would otherwise be a running plaintext list of
171	// every address anyone tried to sign in as — including typos and addresses that
172	// have no account — which is a small pile of personal data this feature has no
173	// reason to hold.
174	const EMAIL_KEY_SALT = randomBytes(16).toString("hex");
175	function emailKey(email: string): string {
176	  return createHash("sha256").update(`${EMAIL_KEY_SALT}:${email.trim().toLowerCase()}`).digest("hex");
177	}
178	
179	type Rule = { limit: number; windowMs: number };
180	type Verdict = { allowed: boolean; retryAfterSeconds?: number };
181	
182	const MINUTE = 60_000;
183	const HOUR = 60 * MINUTE;
184	const DAY = 24 * HOUR;
185	
186	// Two windows per bucket rather than one: a short window stops a burst, and a
187	// long one stops a patient attacker who paces themselves just under it.
188	const LOGIN_IP_RULES: Rule[] = [
189	  { limit: 20, windowMs: 15 * MINUTE },
190	  { limit: 60, windowMs: HOUR },
191	];
192	
193	// Per ACCOUNT, across every source address. This is the rule that actually
194	// answers credential stuffing, where the whole point is that each guess arrives
195	// from a different IP. Tighter than the per-IP rule because a single account
196	// legitimately sees very few failures.
197	//
198	// The tradeoff is real and is chosen with eyes open: anyone can burn a victim's
199	// account bucket on purpose and cost them a login for a few minutes. That is
200	// why this is a ROLLING WINDOW that heals by itself, never a sticky lockout
201	// flag, and why a correct password clears it immediately — the victim's next
202	// attempt after the window slides succeeds, and no operator action is needed.
203	// An indefinite lockout would trade password guessing for a denial-of-service
204	// against any account whose email address is known.
205	const LOGIN_EMAIL_RULES: Rule[] = [
206	  { limit: 5, windowMs: 15 * MINUTE },
207	  { limit: 20, windowMs: HOUR },
208	];
209	
210	// Signup is a volume problem, not a guessing problem: one source minting many
211	// accounts. Every account that lands costs SIGNUP_GRANT credits of real model
212	// spend, so the daily rule is the one that bounds the money.
213	//
214	// Sized to be invisible to humans and to a shared office address (five accounts
215	// an hour from one IP is already an odd thing for real people to do) while
216	// capping what a single address can mint per day. A distributed botnet still
217	// gets one bucket per address — no IP-keyed limiter can fix that, and the
218	// answers to it are email verification before the grant lands, or deferring the
219	// grant until first build. Both are outside this file.
220	const SIGNUP_IP_RULES: Rule[] = [
221	  { limit: 5, windowMs: HOUR },
222	  { limit: 15, windowMs: DAY },
223	];
224	
225	const loginIpHits = new Map<string, number[]>();
226	const loginEmailHits = new Map<string, number[]>();
227	const signupIpHits = new Map<string, number[]>();
228	
229	// Ceiling on distinct keys per map, so a flood of unique addresses cannot grow
230	// memory without bound.
231	const MAX_KEYS = 20_000;
232	
233	function longestWindow(rules: Rule[]): number {
234	  return Math.max(...rules.map((r) => r.windowMs));
235	}
236	
237	/**
238	 * Keep a map under MAX_KEYS.
239	 *
240	 * NOTE the difference from checkEnhanceRateLimit above, which clears wholesale
241	 * when it grows too large. That is fine for a speed bump on an authenticated
242	 * route; here it would be a vulnerability — an attacker could flood unique keys
243	 * to force a clear and wipe the very counter that is throttling them. So this
244	 * only ever drops entries that are already expired, and if that is not enough,
245	 * evicts the LEAST recently active first. An attacker's own bucket is by
246	 * definition the most recently active, so it is the last thing to go.
247	 */
248	function sweep(store: Map<string, number[]>, now: number, windowMs: number): void {
249	  if (store.size <= MAX_KEYS) return;
250	
251	  for (const [key, hits] of store) {
252	    if (hits.length === 0 || hits[hits.length - 1] <= now - windowMs) store.delete(key);
253	  }
254	  if (store.size <= MAX_KEYS) return;
255	
256	  const byLastSeen = [...store.entries()].sort(
257	    (a, b) => a[1][a[1].length - 1] - b[1][b[1].length - 1],
258	  );
259	  for (const [key] of byLastSeen.slice(0, store.size - MAX_KEYS)) store.delete(key);
260	}
261	
262	/** Read-only: would one more hit on this key breach any of its rules? */
263	function check(store: Map<string, number[]>, key: string, rules: Rule[]): Verdict {
264	  const now = Date.now();
265	  const hits = (store.get(key) ?? []).filter((t) => t > now - longestWindow(rules));
266	
267	  let retryAfterSeconds = 0;
268	  for (const rule of rules) {
269	    const inWindow = hits.filter((t) => t > now - rule.windowMs);
270	    if (inWindow.length < rule.limit) continue;
271	    // Wait only until enough hits age out of THIS window, not a flat period.
272	    const binding = inWindow[inWindow.length - rule.limit];
273	    retryAfterSeconds = Math.max(
274	      retryAfterSeconds,
275	      Math.max(1, Math.ceil((binding + rule.windowMs - now) / 1000)),
276	    );
277	  }
278	
279	  return retryAfterSeconds > 0 ? { allowed: false, retryAfterSeconds } : { allowed: true };
280	}
281	
282	function record(store: Map<string, number[]>, key: string, rules: Rule[]): void {
283	  const now = Date.now();
284	  const windowMs = longestWindow(rules);
285	  sweep(store, now, windowMs);
286	  const hits = (store.get(key) ?? []).filter((t) => t > now - windowMs);
287	  hits.push(now);
288	  store.set(key, hits);
289	}
290	
291	/** Give back the single most recent hit on a key. */
292	function refund(store: Map<string, number[]>, key: string): void {
293	  const hits = store.get(key);
294	  if (!hits || hits.length === 0) return;
295	  hits.pop();
296	  if (hits.length === 0) store.delete(key);
297	  else store.set(key, hits);
298	}
299	
300	/**
301	 * Gate one sign-in attempt. Call BEFORE looking the user up or hashing
302	 * anything, and treat `allowed: false` as the end of the request.
303	 *
304	 * WHY THIS CONSUMES ON EVERY ATTEMPT RATHER THAN COUNTING FAILURES: counting
305	 * only failures means the counter is written after `verifyPassword` resolves,
306	 * and everything between is an `await`. A thousand concurrent guesses would all
307	 * pass the check before the first failure was ever recorded — the limiter would
308	 * read as correct and stop nothing. Consuming up front closes that window,
309	 * because the check and the record here happen in one synchronous run with no
310	 * await between them. A correct password is then refunded by noteLoginSuccess,
311	 * which gets back the failure-counting behaviour without the race.
312	 *
313	 * The verdict is identical whether or not `email` belongs to a real account —
314	 * the account bucket fills on attempts, not on hits — so a 429 tells an
315	 * enumerating caller nothing that a 401 would not.
316	 */
317	export function checkLoginRateLimit(req: Request, email: string): Verdict {
318	  const ip = clientIp(req);
319	  const account = emailKey(email);
320	
321	  // Both verdicts are taken before either is consumed. Otherwise an attacker
322	  // already blocked on their own IP would keep filling victims' account buckets
323	  // — turning a limiter into a lockout tool.
324	  const byIp = check(loginIpHits, ip, LOGIN_IP_RULES);
325	  const byAccount = check(loginEmailHits, account, LOGIN_EMAIL_RULES);
326	  if (!byIp.allowed || !byAccount.allowed) {
327	    return {
328	      allowed: false,
329	      retryAfterSeconds: Math.max(byIp.retryAfterSeconds ?? 0, byAccount.retryAfterSeconds ?? 0),
330	    };
331	  }
332	
333	  record(loginIpHits, ip, LOGIN_IP_RULES);
334	  record(loginEmailHits, account, LOGIN_EMAIL_RULES);
335	  return { allowed: true };
336	}
337	
338	/**
339	 * Call after a password verifies. Clears the account's bucket outright, and
340	 * refunds this attempt against the IP's.
341	 *
342	 * The two are treated differently on purpose. Clearing the account bucket is
343	 * safe: whoever just proved they hold the password is entitled to that account.
344	 * The IP bucket is only REFUNDED — one hit, the successful one — so that a NAT
345	 * shared by hundreds of people is never spent by people signing in correctly,
346	 * while an attacker who happens to own one valid account cannot log into it
347	 * repeatedly to wipe the guesses they are making against everyone else.
348	 */
349	export function noteLoginSuccess(req: Request, email: string): void {
350	  loginEmailHits.delete(emailKey(email));
351	  refund(loginIpHits, clientIp(req));
352	}
353	
354	/**
355	 * Gate one signup attempt. Call once the request is well-formed and BEFORE the
356	 * existence check, so that hammering signup to learn which emails are already
357	 * registered is throttled by the same counter as account minting.
358	 *
359	 * Consumes on every attempt, with no refund for success — unlike login, a
360	 * successful signup is precisely the expensive event we are limiting.
361	 */
362	export function checkSignupRateLimit(req: Request): Verdict {
363	  const ip = clientIp(req);
364	  const verdict = check(signupIpHits, ip, SIGNUP_IP_RULES);
365	  if (!verdict.allowed) return verdict;
366	  record(signupIpHits, ip, SIGNUP_IP_RULES);
367	  return { allowed: true };
368	}
369	
370	/**
371	 * The one message either auth route shows when it throttles. Uniform by
372	 * design: it must not differ between the per-IP and the per-account rule, or
373	 * between a registered address and an unregistered one, because the difference
374	 * would itself be the answer to "does this account exist".
375	 */
376	export const RATE_LIMITED_MESSAGE = "Too many attempts. Please wait a moment and try again.";
