// Behavioural verification for the durable pre-auth rate limiter.
// Run:  node --env-file=C:/Users/edmem/kodely-prod/.env <this file>
import { registerHooks } from "node:module";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

// lib/*.ts use extensionless relative imports (bundler resolution). Teach the
// ESM loader to find them so the real module can be exercised as-is.
registerHooks({
  resolve(specifier, context, nextResolve) {
    if (specifier.startsWith(".") && !/\.[cm]?[jt]sx?$/.test(specifier)) {
      const base = new URL(specifier, context.parentURL);
      for (const ext of [".ts", ".tsx", ".js"]) {
        const cand = new URL(base.href + ext);
        if (existsSync(fileURLToPath(cand))) return { url: cand.href, shortCircuit: true };
      }
    }
    return nextResolve(specifier, context);
  },
});

const ROOT = "file:///C:/Users/edmem/kodely-prod";
const { db } = await import(`${ROOT}/lib/db.ts`);

let boots = 0;
/** A brand-new module instance: everything in-process is gone. A restart. */
const boot = () => import(`${ROOT}/lib/rate-limit.ts?boot=${++boots}`);

const req = (ip) =>
  new Request("https://kodely.dev/api/auth/login", ip ? { headers: { "cf-connecting-ip": ip } } : {});

let pass = 0;
const failures = [];
function ok(label, cond, detail = "") {
  if (cond) {
    pass++;
    console.log(`  PASS  ${label}${detail ? ` — ${detail}` : ""}`);
  } else {
    failures.push(label);
    console.log(`  FAIL  ${label}${detail ? ` — ${detail}` : ""}`);
  }
}
const eq = (label, actual, expected) =>
  ok(label, actual === expected, `got ${JSON.stringify(actual)}, want ${JSON.stringify(expected)}`);

const rows = (where = {}) => db.loginAttempt.count({ where });
const wipe = () => db.loginAttempt.deleteMany({});
const shift = (scope, seconds) =>
  db.$executeRawUnsafe(
    `UPDATE "LoginAttempt" SET "createdAt" = "createdAt" - make_interval(secs => $1) WHERE scope = $2`,
    seconds,
    scope,
  );

const startRows = await rows();
console.log(`LoginAttempt rows before: ${startRows}`);
if (startRows !== 0) {
  console.log("Refusing to run against a non-empty table.");
  process.exit(1);
}
const startedAt = new Date();

// ---------------------------------------------------------------------------
console.log("\n[1] caps trip at exactly the right count");
{
  await wipe();
  const rl = await boot();
  await rl.syncLoginAttempts();

  let allowed = 0;
  for (let i = 0; i < 20; i++) {
    if (rl.checkLoginRateLimit(req("198.51.100.1"), `u${i}@example.invalid`).allowed) allowed++;
  }
  eq("20 attempts from one IP (distinct emails) all allowed", allowed, 20);

  const v = rl.checkLoginRateLimit(req("198.51.100.1"), "u20@example.invalid");
  eq("21st denied", v.allowed, false);
  ok(
    "retryAfter is bounded by the 15-minute window",
    v.retryAfterSeconds > 0 && v.retryAfterSeconds <= 900,
    `${v.retryAfterSeconds}s`,
  );

  await rl.syncLoginAttempts();
  eq("20 ip rows written", await rows({ scope: "ip" }), 20);
  eq("20 account rows written", await rows({ scope: "account" }), 20);

  // Account cap, isolated from the IP cap by using a distinct IP per attempt.
  await wipe();
  const rl2 = await boot();
  await rl2.syncLoginAttempts();
  let a = 0;
  for (let i = 0; i < 5; i++) {
    if (rl2.checkLoginRateLimit(req(`203.0.113.${i}`), "victim@example.invalid").allowed) a++;
  }
  eq("5 attempts on one account from 5 IPs all allowed", a, 5);
  const v2 = rl2.checkLoginRateLimit(req("203.0.113.9"), "victim@example.invalid");
  eq("6th on that account denied, from a fresh IP", v2.allowed, false);
  eq("the fresh IP itself is not what blocked it", rl2.checkLoginRateLimit(req("203.0.113.9"), "other@example.invalid").allowed, true);
}

// ---------------------------------------------------------------------------
console.log("\n[2] the window rolls; it is not a flat block");
{
  await wipe();
  const rl = await boot();
  await rl.syncLoginAttempts();
  for (let i = 0; i < 5; i++) rl.checkLoginRateLimit(req(`203.0.113.${i}`), "roll@example.invalid");
  await rl.syncLoginAttempts();

  const v0 = rl.checkLoginRateLimit(req("203.0.113.50"), "roll@example.invalid");
  ok("blocked, ~900s to wait while all 5 hits are fresh", v0.allowed === false && v0.retryAfterSeconds > 890, `${v0.retryAfterSeconds}s`);

  await shift("account", 600);
  await rl.syncLoginAttempts();
  const v1 = rl.checkLoginRateLimit(req("203.0.113.51"), "roll@example.invalid");
  ok(
    "still blocked 10 minutes later, but the wait has shrunk to ~300s",
    v1.allowed === false && v1.retryAfterSeconds > 250 && v1.retryAfterSeconds < 340,
    `${v1.retryAfterSeconds}s`,
  );

  await shift("account", 305);
  await rl.syncLoginAttempts();
  const v2 = rl.checkLoginRateLimit(req("203.0.113.52"), "roll@example.invalid");
  eq("allowed once the oldest hits age out of the 15-minute window", v2.allowed, true);
  eq("the aged-out hits are still counted by the 1-hour rule", await rows({ scope: "account" }), 6);
}

// ---------------------------------------------------------------------------
console.log("\n[3] a correct password clears the account bucket and refunds one IP hit");
{
  await wipe();
  const rl = await boot();
  await rl.syncLoginAttempts();
  for (let i = 0; i < 5; i++) rl.checkLoginRateLimit(req("192.0.2.7"), "real@example.invalid");
  await rl.syncLoginAttempts();
  eq("5 ip hits", await rows({ scope: "ip" }), 5);
  eq("5 account hits", await rows({ scope: "account" }), 5);

  const blocked = rl.checkLoginRateLimit(req("192.0.2.7"), "real@example.invalid");
  eq("6th blocked by the account rule", blocked.allowed, false);
  await rl.syncLoginAttempts();
  eq("a blocked attempt consumes nothing (ip)", await rows({ scope: "ip" }), 5);
  eq("a blocked attempt consumes nothing (account)", await rows({ scope: "account" }), 5);

  rl.noteLoginSuccess(req("192.0.2.7"), "real@example.invalid");
  await rl.syncLoginAttempts();
  eq("account bucket cleared outright", await rows({ scope: "account" }), 0);
  eq("IP bucket refunded exactly one hit, not cleared", await rows({ scope: "ip" }), 4);
  eq("the account can sign in again immediately", rl.checkLoginRateLimit(req("192.0.2.7"), "real@example.invalid").allowed, true);

  // The refund is not a wipe: an attacker who owns one account cannot log into
  // it repeatedly to erase the guesses they are making against everyone else.
  await wipe();
  const rl2 = await boot();
  await rl2.syncLoginAttempts();
  for (let i = 0; i < 19; i++) rl2.checkLoginRateLimit(req("192.0.2.8"), `mark${i}@example.invalid`);
  for (let i = 0; i < 6; i++) {
    rl2.checkLoginRateLimit(req("192.0.2.8"), "mine@example.invalid");
    rl2.noteLoginSuccess(req("192.0.2.8"), "mine@example.invalid");
  }
  await rl2.syncLoginAttempts();
  eq("19 guesses + 6 correct logins leaves the IP bucket at 19", await rows({ scope: "ip" }), 19);
  eq("the 20th guess is the last one the IP gets", rl2.checkLoginRateLimit(req("192.0.2.8"), "last@example.invalid").allowed, true);
  eq("the 21st is refused despite six successful logins in between", rl2.checkLoginRateLimit(req("192.0.2.8"), "nope@example.invalid").allowed, false);
}

// ---------------------------------------------------------------------------
console.log("\n[4] the two login buckets compose, and neither is consumed unless both pass");
{
  await wipe();
  const rl = await boot();
  await rl.syncLoginAttempts();
  for (let i = 0; i < 20; i++) rl.checkLoginRateLimit(req("198.51.100.9"), `spread${i}@example.invalid`);
  await rl.syncLoginAttempts();

  const v = rl.checkLoginRateLimit(req("198.51.100.9"), "untouched@example.invalid");
  eq("IP is spent, so a fresh account is refused too", v.allowed, false);
  await rl.syncLoginAttempts();
  eq("but the fresh account's bucket was NOT charged", await rows({ scope: "account" }), 20);

  eq(
    "and that account still signs in fine from another address",
    rl.checkLoginRateLimit(req("198.51.100.10"), "untouched@example.invalid").allowed,
    true,
  );
  eq(
    "an account already targeted 20 times is blocked from any address",
    rl.checkLoginRateLimit(req("198.51.100.11"), "spread0@example.invalid").allowed,
    true,
  );
}

// ---------------------------------------------------------------------------
console.log("\n[5] THE POINT: the counter survives a process restart");
{
  await wipe();
  const before = await boot();
  await before.syncLoginAttempts();
  for (let i = 0; i < 20; i++) before.checkLoginRateLimit(req("198.51.100.77"), `pre${i}@example.invalid`);
  eq("20 attempts spent before the restart", before.checkLoginRateLimit(req("198.51.100.77"), "pre20@example.invalid").allowed, false);
  await before.syncLoginAttempts();
  eq("20 rows are durable in LoginAttempt", await rows({ scope: "ip" }), 20);

  // --- process restart: a module instance with nothing in memory ---
  const after = await boot();
  const cold = after.checkLoginRateLimit(req("198.51.100.78"), "cold@example.invalid");
  ok("cold start fails CLOSED, not open", cold.allowed === false && cold.retryAfterSeconds === 1, JSON.stringify(cold));
  await after.syncLoginAttempts();
  eq("the cold-start refusal consumed nothing", await rows({ scope: "ip" }), 20);

  eq(
    "after the restart the spent IP is STILL refused",
    after.checkLoginRateLimit(req("198.51.100.77"), "post@example.invalid").allowed,
    false,
  );
  eq(
    "and an unrelated IP is served normally (hydration is not a blanket block)",
    after.checkLoginRateLimit(req("198.51.100.79"), "post@example.invalid").allowed,
    true,
  );

  // Control: the denial above came from the ROWS. Remove them, restart again,
  // and the same IP walks through — which is exactly what the old in-memory
  // limiter did on every deploy.
  await wipe();
  const control = await boot();
  await control.syncLoginAttempts();
  eq(
    "control: with the rows gone, the same IP is allowed again",
    control.checkLoginRateLimit(req("198.51.100.77"), "ctl@example.invalid").allowed,
    true,
  );

  // Account scope survives too, and the digest is stable across boots — a
  // per-process salt would have handed this account a brand-new bucket.
  await wipe();
  const a1 = await boot();
  await a1.syncLoginAttempts();
  for (let i = 0; i < 5; i++) a1.checkLoginRateLimit(req(`203.0.113.${100 + i}`), "survivor@example.invalid");
  await a1.syncLoginAttempts();
  const a2 = await boot();
  await a2.syncLoginAttempts();
  eq(
    "an account bucket survives a restart (stable email digest)",
    a2.checkLoginRateLimit(req("203.0.113.120"), "survivor@example.invalid").allowed,
    false,
  );
}

// ---------------------------------------------------------------------------
console.log("\n[6] signup: hourly and daily rules, and they survive a restart too");
{
  await wipe();
  const rl = await boot();
  await rl.syncLoginAttempts();
  let n = 0;
  for (let i = 0; i < 5; i++) if (rl.checkSignupRateLimit(req("192.0.2.44")).allowed) n++;
  eq("5 signups an hour allowed", n, 5);
  const v = rl.checkSignupRateLimit(req("192.0.2.44"));
  ok("6th refused within the hour", v.allowed === false && v.retryAfterSeconds <= 3600, `${v.retryAfterSeconds}s`);

  await rl.syncLoginAttempts();
  const restarted = await boot();
  await restarted.syncLoginAttempts();
  eq("still refused after a restart", restarted.checkSignupRateLimit(req("192.0.2.44")).allowed, false);

  // Age the first batch past the hourly window twice; the DAILY rule then binds.
  await shift("signup", 3700);
  await restarted.syncLoginAttempts();
  let m = 0;
  for (let i = 0; i < 5; i++) if (restarted.checkSignupRateLimit(req("192.0.2.44")).allowed) m++;
  eq("hourly window healed: 5 more allowed", m, 5);
  await restarted.syncLoginAttempts();
  await shift("signup", 3700);
  await restarted.syncLoginAttempts();
  let k = 0;
  for (let i = 0; i < 5; i++) if (restarted.checkSignupRateLimit(req("192.0.2.44")).allowed) k++;
