async function prune(): Promise<void> {
  const cutoff = new Date(Date.now() - MAX_WINDOW - PRUNE_GRACE_MS);
  for (let i = 0; i < PRUNE_MAX_BATCHES; i++) {
    // The subselect is an ordered range scan of LoginAttempt_createdAt_idx with
    // a LIMIT; the delete is by primary key.
    const deleted = await db.$executeRaw`
      DELETE FROM "LoginAttempt"
      WHERE id IN (
        SELECT id FROM "LoginAttempt"
        WHERE "createdAt" < ${cutoff}
        ORDER BY "createdAt" ASC
        LIMIT ${PRUNE_BATCH}
      )`;
    if (deleted < PRUNE_BATCH) return;
  }
}

