const { db } = await import(`${ROOT}/lib/db.ts`);

let boots = 0;
const live = [];
/** A brand-new module instance: nothing in memory. A process restart. */
const boot = async () => {
  const m = await import(`${ROOT}/lib/rate-limit.ts?boot=${++boots}`);
  live.push(m);
  return m;
};
