const flushAll = async () => {
  for (const m of live) await m.syncLoginAttempts();
};

const req = (ip) =>
  new Request("https://kodely.dev/api/auth/login", ip ? { headers: { "cf-connecting-ip": ip } } : {});

let pass = 0;
